-- Reference seed (part 03.07): the feature flag (OFF by default, ON in development and test), the widget registry, the two system dashboards (My Work and
-- Requests Overview) and their pages in the navigation registry. The data of every widget comes from a provider registered in code under its code.
INSERT OR IGNORE INTO core_feature_flags (key, description, default_enabled, environment, enabled, created_by, source_type)
VALUES ('ff.ui.p0307', 'Part 03.07 dashboard and widget framework and My Work', 0, NULL, 0, 'migration', 'reference_seed');
INSERT OR IGNORE INTO core_feature_flags (key, description, default_enabled, environment, enabled, created_by, source_type)
SELECT 'ff.ui.p0307', 'Part 03.07 dashboard and widget framework and My Work', 0, env.name, 1, 'migration', 'reference_seed'
FROM (SELECT 'development' AS name UNION ALL SELECT 'test') AS env;
